<script lang="ts">
  import { onMount } from "svelte";
  import type { JobRecord, LlamaBenchArgs, LlamaPerplexityArgs } from "@obsidianlm/shared";
  import PageHeader from "../components/PageHeader.svelte"; import Panel from "../components/Panel.svelte"; import StatusBadge from "../components/StatusBadge.svelte"; import CopyButton from "../components/CopyButton.svelte";
  import { API_ENDPOINTS, fetchJson, type JobListResponse, type JobLogsResponse, type LlamaBuildDiscoveryResponse, type ModelDiscoveryResponse, type ToolInputDiscoveryResponse } from "../api";
  import { createCompletionAwarePoller, type CompletionAwarePoller } from "../polling";
  type Fields = Record<string, string | number>;
  let jobs: JobRecord[] = [], builds: LlamaBuildDiscoveryResponse["builds"] = [], models: ModelDiscoveryResponse["models"] = [], datasets: ToolInputDiscoveryResponse["files"] = [], selectedId = "", tab: "bench" | "perplexity" = "bench", toolKey = "", modelPath = "", datasetPath = "", values: Fields = {}, logs: string[] = [], message = "", loading = true, poller: CompletionAwarePoller | undefined, staticLoaded = false, destroyed = false;
  const benchFields = [["threads", "Threads"], ["batchSize", "Batch size"], ["ubatchSize", "Micro batch"], ["nGpuLayers", "GPU layers"], ["promptTokens", "Prompt tokens"], ["generationTokens", "Generation tokens"], ["repetitions", "Repetitions"]] as const;
  const pplFields = [["threads", "Threads"], ["ctxSize", "Context size"], ["batchSize", "Batch size"], ["ubatchSize", "Micro batch"], ["nGpuLayers", "GPU layers"]] as const;
  $: selected = jobs.find((job) => job.id === selectedId) ?? jobs[0]; $: active = jobs.find((job) => job.status === "queued" || job.status === "running");
  $: if (active && poller) poller.start();
  $: tools = builds.flatMap((build) => build.tools.filter((tool) => tool.kind === (tab === "bench" ? "bench" : "perplexity")).map((tool) => ({ key: `${build.id}|${tool.path}`, build, tool })));
  $: choice = tools.find((item) => item.key === toolKey); $: filteredModels = models.filter((model) => model.artifactKindGuess === "model" || !model.artifactKindGuess || model.artifactKindGuess === "unknown"); $: fields = tab === "bench" ? benchFields : pplFields;
  function tone(status: JobRecord["status"]): "green" | "amber" | "red" | "muted" { return status === "completed" ? "green" : status === "running" || status === "queued" ? "amber" : status === "failed" ? "red" : "muted"; }
  function duration(job: JobRecord) { const start = new Date(job.startedAt ?? job.createdAt).getTime(), end = new Date(job.finishedAt ?? Date.now()).getTime(); return job.startedAt ? `${Math.max(0, Math.round((end - start) / 1000))}s` : "—"; }
  function numberArgs(): LlamaBenchArgs | LlamaPerplexityArgs { return Object.fromEntries(Object.entries(values).flatMap(([key, value]) => { const number = Number(value); return String(value).trim() && Number.isFinite(number) ? [[key, number]] : []; })); }
  async function load() { try { const list = await fetchJson<JobListResponse>(API_ENDPOINTS.jobs.list); if (!staticLoaded) { const [buildData, modelData, inputData] = await Promise.all([fetchJson<LlamaBuildDiscoveryResponse>(API_ENDPOINTS.discovery.llamaBuilds), fetchJson<ModelDiscoveryResponse>(API_ENDPOINTS.discovery.models), fetchJson<ToolInputDiscoveryResponse>(API_ENDPOINTS.discovery.toolInputs)]); if (destroyed) return; builds = buildData.builds; models = modelData.models; datasets = inputData.files; staticLoaded = true; } if (destroyed) return; jobs = list.jobs.slice(0, 100); } catch (error) { if (!destroyed) message = error instanceof Error ? error.message : "Could not load jobs"; } finally { if (!destroyed) loading = false; } }
  async function poll() { await load(); if (!jobs.some((job) => job.status === "queued" || job.status === "running")) poller?.stop(); }
  async function select(job: JobRecord) { selectedId = job.id; try { logs = (await fetchJson<JobLogsResponse>(API_ENDPOINTS.jobs.logs(job.id, 200))).logs; } catch (error) { logs = []; message = error instanceof Error ? error.message : "Could not load job logs"; } }
  async function start() { if (!choice || !modelPath || (tab === "perplexity" && !datasetPath)) { message = "Choose valid discovered tool, model, and dataset."; return; } const body = tab === "bench" ? { buildId: choice.build.id, benchPath: choice.tool.path, modelPath, args: numberArgs() } : { buildId: choice.build.id, perplexityPath: choice.tool.path, modelPath, datasetPath, args: numberArgs() }; try { await fetchJson(tab === "bench" ? API_ENDPOINTS.jobs.llamaBench : API_ENDPOINTS.jobs.llamaPerplexity, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify(body) }); message = "Job queued."; await poller?.refresh(); poller?.start(); } catch (error) { message = error instanceof Error ? error.message : "Could not start job"; } }
  async function cancel() { if (!active) return; try { await fetchJson(API_ENDPOINTS.jobs.cancel(active.id), { method: "POST" }); message = "Cancellation requested."; await poller?.refresh(); poller?.start(); } catch (error) { message = error instanceof Error ? error.message : "Could not cancel job"; } }
  onMount(() => { destroyed = false; poller = createCompletionAwarePoller(poll, 2000); poller.start(); return () => { destroyed = true; poller?.stop(); }; });
</script>
<main class="page-surface jobs-page" aria-label="Jobs"><PageHeader title="Jobs" subtitle="Run bounded llama.cpp benchmarks and inspect recent results." /><div class="actions"><StatusBadge label={active ? `Active: ${active.status}` : "No active job"} tone={active ? "amber" : "muted"} /><button class="btn" on:click={() => void load()} type="button">Refresh</button><button class="btn danger" on:click={() => void cancel()} disabled={!active} type="button">Cancel current</button><span role="status" aria-live="polite">{message}</span></div><div class="tabs" role="tablist"><button class:active={tab === "bench"} on:click={() => tab = "bench"} type="button">Benchmark</button><button class:active={tab === "perplexity"} on:click={() => tab = "perplexity"} type="button">Perplexity</button></div><div class="layout"><Panel title="New job"><div class="form"><label>Discovered {tab} tool<select bind:value={toolKey}><option value="">Select tool</option>{#each tools as item}<option value={item.key}>{item.build.name} — {item.tool.fileName}</option>{/each}</select></label><label>Primary model<select bind:value={modelPath}><option value="">Select model</option>{#each filteredModels as model}<option value={model.path}>{model.name}</option>{/each}</select></label>{#if tab === "perplexity"}<label>Discovered dataset<select bind:value={datasetPath}><option value="">Select dataset</option>{#each datasets as file}<option value={file.path}>{file.name}</option>{/each}</select></label>{/if}<div class="number-grid">{#each fields as field}<label>{field[1]}<input type="number" bind:value={values[field[0]]} /></label>{/each}</div>{#if choice}<p class="selection">Tool: {choice.tool.fileName} · Build: {choice.build.name} · Model: {filteredModels.find((model) => model.path === modelPath)?.name ?? "Select model"}{datasetPath ? ` · Dataset: ${datasets.find((file) => file.path === datasetPath)?.name ?? ""}` : ""}</p>{/if}<button class="btn primary" on:click={() => void start()} disabled={!!active || loading} type="button">{active ? "Wait for active job" : `Run ${tab}`}</button></div></Panel><Panel title="Recent jobs"><div class="history">{#each jobs as job}<button class:chosen={selected?.id === job.id} on:click={() => void select(job)} type="button"><span>{job.type}</span><StatusBadge label={job.status} tone={tone(job.status)} /><time>Created {new Date(job.createdAt).toLocaleString()} · Started {job.startedAt ? new Date(job.startedAt).toLocaleString() : "—"} · Duration {duration(job)}</time></button>{:else}<p> {loading ? "Loading jobs…" : "No jobs have run yet."}</p>{/each}</div></Panel></div>{#if selected}<Panel title="Selected job"><div class="detail"><StatusBadge label={selected.status} tone={tone(selected.status)} /><p><b>Selection:</b> {selected.selection?.tool ?? "unknown tool"} · {selected.selection?.build ?? "unknown build"} · {selected.selection?.model ?? "unknown model"}{selected.selection?.dataset ? ` · ${selected.selection.dataset}` : ""}</p><p><b>Created:</b> {new Date(selected.createdAt).toLocaleString()} · <b>Started:</b> {selected.startedAt ? new Date(selected.startedAt).toLocaleString() : "—"} · <b>Elapsed/duration:</b> {duration(selected)}</p>{#if selected.result?.type === "llama-bench"}<div class="result"><b>Benchmark results</b>{#each selected.result.rows as row}<p>{row.test} · {row.tokensPerSecond ?? "—"} tok/s · threads {row.threads ?? "—"} · GPU layers {row.gpuLayers ?? "—"}</p>{/each}</div>{:else if selected.result?.type === "llama-perplexity"}<div class="result"><b>Perplexity</b><p>Final PPL: {selected.result.finalPpl ?? "—"} · Uncertainty: {selected.result.uncertainty ?? "—"} · Estimates: {selected.result.estimateCount}</p></div>{/if}<div class="log-head"><b>Job logs</b><button class="btn" on:click={() => void select(selected)} type="button">Refresh</button><CopyButton value={logs.join("\n")} label="Copy" /></div><pre>{logs.join("\n") || "No job logs available."}</pre><a href={`#logs?job=${selected.id}`}>Open in Logs</a></div></Panel>{/if}</main>
<style>.actions,.tabs,.log-head{display:flex;gap:.6rem;align-items:center;flex-wrap:wrap;margin-bottom:.8rem}.actions span{color:var(--color-muted);font-size:.8rem}.tabs button{border:0;border-bottom:2px solid transparent;background:transparent;color:var(--color-muted);padding:.5rem .8rem}.tabs button.active{color:var(--color-text);border-color:var(--color-purple)}.layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(18rem,1fr);gap:1rem;margin-bottom:1rem}.form,.detail{display:grid;gap:.75rem;padding:1rem}.form label,.number-grid label{display:grid;gap:.3rem;font-size:.8rem;color:var(--color-muted)}.number-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.5rem}.selection{margin:0;color:var(--color-muted);font-size:.8rem}.history{max-height:28rem;overflow:auto}.history button{display:grid;grid-template-columns:1fr auto;gap:.5rem;width:100%;padding:.7rem 1rem;border:0;border-bottom:1px solid var(--color-line);background:transparent;color:inherit;text-align:left}.history button.chosen{background:var(--color-panel-strong)}.history time{grid-column:1/-1;color:var(--color-muted);font-size:.75rem}.detail p{margin:0;overflow-wrap:anywhere}.detail pre{max-height:14rem;overflow:auto;margin:0;padding:.75rem;background:#070d17;white-space:pre-wrap}.result{display:grid;gap:.3rem}.result p{font-size:.85rem}@media(max-width:700px){.layout{grid-template-columns:1fr}.number-grid{grid-template-columns:1fr}}</style>
